rule "vmware app from message"
when
  has_field("message") &&
  !has_field("application_name")
then
  let msg = to_string($message.message);
  let m = regex("^[A-Za-z0-9._-]+\\s+([A-Za-z][A-Za-z0-9_-]*)(\\[[0-9]+\\])?:", msg);
  let app = to_string(m["0"], "");
  set_field("vmware_app", app);
end
